package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.planning.delivery.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class ReminderDeliveryIntegrationTest {
 static class Time extends Clock {Instant now=Instant.parse("2028-01-01T00:00:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now;}void advance(long seconds){now=now.plusSeconds(seconds);}}
 PGSimpleDataSource ds;JdbcTemplate sql;String schema;Time time;ScheduleStore schedules;ReminderStore reminders;ReminderDeliveryStore deliveries;UUID space,actor;UuidV7 ids;String trace="a".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="dispatch_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);time=new Time();ids=new UuidV7(time);space=ids.next();actor=ids.next();schedules=new ScheduleStore(ds,time);reminders=new ReminderStore(ds,time);deliveries=new ReminderDeliveryStore(ds,time);}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 ReminderStore.Reminder reminder(){var s=schedules.create(space,actor,key(),new ScheduleStore.Input("Dispatch title","",time.now.plusSeconds(120).toString(),time.now.plusSeconds(180).toString(),"UTC",null),trace).schedule();var i=new ReminderRules.Input(s.scheduleId(),1,1);return reminders.create(space,actor,key(),i,reminders.preview(space,i).previewHash(),trace).reminder();}
 ReminderDeliveryStore.Delivery arm(ReminderStore.Reminder m){return deliveries.arm(space,m.reminderId(),actor,m.version(),key(),trace).delivery();}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 @Test void explicitlyArmedDueFactCommitsOnceWithoutMutatingSettingsOrSchedule()throws Exception{var m=reminder();String key=key();var first=deliveries.arm(space,m.reminderId(),actor,1,key,trace);var v=first.delivery();assertFalse(deliveries.process(v.deliveryId()));assertTrue(deliveries.candidates(100).isEmpty());time.advance(61);assertTrue(deliveries.process(v.deliveryId()));assertFalse(deliveries.process(v.deliveryId()));var sent=deliveries.get(space,m.reminderId(),v.deliveryId());assertEquals("DISPATCHED",sent.state());assertEquals(2,sent.version());assertEquals(m,reminders.get(space,m.reminderId()));assertEquals(1,schedules.get(space,m.input().scheduleId()).version());assertEquals(sent,deliveries.arm(space,m.reminderId(),ids.next(),1,key,trace).delivery());status(409,()->deliveries.cancel(space,m.reminderId(),v.deliveryId(),actor,2,trace));var exported=deliveries.export(null,50);assertEquals(1,exported.items().size());var e=ReminderDeliveryEnvelopeV1.parseFrom(Base64.getDecoder().decode(exported.items().getFirst().envelope()));var p=ReminderDeliveryPayloadV1.parseFrom(e.getPayload());assertEquals("ReminderDispatched",e.getEventType());assertEquals(actor.toString(),e.getActorId());assertEquals(trace,e.getTraceId());assertEquals(m.remindsAt(),p.getRemindsAt());assertEquals(m.schedule().startsOffset(),p.getStartsOffset());assertEquals(List.of(2L,1L),deliveries.history(space,m.reminderId(),v.deliveryId(),Long.MAX_VALUE,5).stream().map(ReminderDeliveryStore.Revision::version).toList());}
 @Test void changedScheduleReminderAndRetiredSourcesSuppressEvenBeforeDue(){for(int reason=0;reason<4;reason++){var m=reminder();var v=arm(m);var s=schedules.get(space,m.input().scheduleId());if(reason==0)schedules.change(space,s.scheduleId(),actor,1,new ScheduleStore.Input("Renamed source","",s.startsAt(),s.endsAt(),s.timeZone(),null),false,trace);if(reason==1){var i=new ReminderRules.Input(s.scheduleId(),1,0);reminders.change(space,m.reminderId(),actor,1,i,reminders.preview(space,i).previewHash(),false,trace);}if(reason==2)reminders.change(space,m.reminderId(),actor,1,null,null,true,trace);if(reason==3)schedules.change(space,s.scheduleId(),actor,1,null,true,trace);assertTrue(deliveries.candidates(100).contains(v.deliveryId()));assertTrue(deliveries.process(v.deliveryId()));assertEquals("SUPPRESSED",deliveries.get(space,m.reminderId(),v.deliveryId()).state());}time.advance(200);assertTrue(deliveries.candidates(100).isEmpty());assertTrue(deliveries.export(null,100).items().isEmpty());}
 @Test void cancellationRearmingAndIntentKeysRemainIndependentOfReminderHistory(){var m=reminder();String key=key();var v=deliveries.arm(space,m.reminderId(),actor,1,key,trace).delivery();status(409,()->arm(m));var cancelled=deliveries.cancel(space,m.reminderId(),v.deliveryId(),actor,1,trace);assertEquals(cancelled,deliveries.cancel(space,m.reminderId(),v.deliveryId(),actor,2,trace));assertEquals(cancelled,deliveries.arm(space,m.reminderId(),actor,1,key,trace).delivery());assertNotEquals(v.deliveryId(),arm(m).deliveryId());status(412,()->deliveries.cancel(space,m.reminderId(),v.deliveryId(),actor,1,trace));assertEquals(1,reminders.history(space,m.reminderId(),Long.MAX_VALUE,5).size());status(404,()->deliveries.get(ids.next(),m.reminderId(),v.deliveryId()));status(412,()->deliveries.arm(space,m.reminderId(),actor,2,key(),trace));var past=reminder();time.advance(61);status(400,()->arm(past));}
 @Test void failedDispatchOutboxRollsBackAttemptAndRetriesSameCanonicalIdentity(){var m=reminder();var v=arm(m);time.advance(61);sql.execute("CREATE FUNCTION fail_dispatch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.type='ReminderDispatched' THEN RAISE EXCEPTION 'controlled dispatch failure'; END IF; RETURN NEW; END $$");sql.execute("CREATE TRIGGER fail_dispatch BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_dispatch()");assertThrows(RuntimeException.class,()->deliveries.process(v.deliveryId()));assertEquals(v,deliveries.get(space,m.reminderId(),v.deliveryId()));assertEquals(1,deliveries.history(space,m.reminderId(),v.deliveryId(),Long.MAX_VALUE,5).size());assertTrue(deliveries.export(null,50).items().isEmpty());sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_dispatch");assertTrue(deliveries.process(v.deliveryId()));assertEquals(1,deliveries.export(null,50).items().size());}
 @Test void concurrentWorkerAndCancelHaveOneTerminalOutcome()throws Exception{var m=reminder();var v=arm(m);time.advance(61);try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return deliveries.process(v.deliveryId());});var b=pool.submit(()->{gate.await();try{return deliveries.cancel(space,m.reminderId(),v.deliveryId(),actor,1,trace).state();}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return "CONFLICT";}});a.get();b.get();var current=deliveries.get(space,m.reminderId(),v.deliveryId());assertTrue(Set.of("CANCELLED","DISPATCHED").contains(current.state()));assertEquals(2,current.version());assertEquals(2,deliveries.history(space,m.reminderId(),v.deliveryId(),Long.MAX_VALUE,10).size());assertEquals(current.state().equals("DISPATCHED")?1:0,deliveries.export(null,50).items().size());}}
}
